import{z as l,x as o,o as A,c as s,q as B,j as t,D as a,d as r,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"因子深化收束","description":"","frontmatter":{"title":"因子深化收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fz-map.md","filePath":"quant/fz-map.md","lastUpdated":1791063341000}'),p={name:"quant/fz-map.md"};function C(d,E,m,D,h,F){const e=o("Mermaid");return A(),s("div",null,[E[2]||(E[2]=B('<h1 id="因子深化收束" tabindex="-1">因子深化收束 <a class="header-anchor" href="#因子深化收束" aria-label="Permalink to &quot;因子深化收束&quot;">​</a></h1><div class="epigraph"><p>每个环节都把「结论相对什么成立」写死：相对控制集、相对家族地图、相对账本、相对试验次数、相对约定表——因子研究的成熟度，就看这些「相对」有没有被省略。</p><footer>—— 本课程十一课方法论的小结口径；文献锚点见各课出处（Fama &amp; French 1993/2015、Carhart 1997、Grinold &amp; Kahn 等）</footer></div><p><a href="/quant/fz-replication-exercise">上一课</a>把报告规范走完了全程：约定对照表、主表、扰动表、复现包归档。因子研究深化这门课到此收束。收束课把十一课排成一条可执行的流水线，并标出每一环最常见的死法——因子研究的失败很少死于某一步算错，多死于环节之间的断裂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流水线的价值在链条的传递方式：每一环的出口是下一环的入口，入口坏了，后面全部在噪声上运算。构造的约定不显式，正交化的控制集就含糊，残差 IR 不可比；拥挤没有状态量，衰减的归因就只剩叙事；状态变量不用 PIT，条件化整个设定作废；报告没有 N 与判据，前面的严谨最后一公里漏光。收束就是检查这些接口，而不是复述各课内容。</p><h3 id="流水线与死法对照" tabindex="-1">流水线与死法对照 <a class="header-anchor" href="#流水线与死法对照" aria-label="Permalink to &quot;流水线与死法对照&quot;">​</a></h3><p><span class="marginnote">一条贯穿的纪律：每环的结论都声明「相对什么成立」——正交化相对控制集，家族坐标相对地图版本，边际 IR 相对当前账本快照，显著性相对试验次数 N，复现相对约定表。「相对」被省略之处，就是下一轮争论的起点。</span></p>',7)),(A(),t(i,null,{default:a(()=>[n(e,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E6%9E%84%E9%80%A0%EF%BC%9A%E7%BA%A6%E5%AE%9A%E6%98%BE%E5%BC%8F%22%5D%20--%3E%20C2%5B%22%E6%AD%A3%E4%BA%A4%E5%8C%96%EF%BC%9A%E6%8E%A7%E5%88%B6%E9%9B%86%3D%E5%81%87%E8%AE%BE%E6%B8%85%E5%8D%95%22%5D%0A%20%20C2%20--%3E%20C3%5B%22%E6%8B%A5%E6%8C%A4%EF%BC%9A%E5%9B%9B%E7%B1%BB%E4%BB%A3%E7%90%86%E7%9A%84%E7%8A%B6%E6%80%81%E9%87%8F%22%5D%0A%20%20C3%20--%3E%20C4%5B%22%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%EF%BC%9A%E8%A1%B0%E5%87%8F%E6%B5%8B%E9%87%8F%E4%B8%8E%E5%BD%92%E5%9B%A0%22%5D%0A%20%20C4%20--%3E%20C5%5B%22%E5%88%86%E7%B1%BB%E5%AD%A6%EF%BC%9A%E5%AE%B6%E6%97%8F%E5%9C%B0%E5%9B%BE%E4%B8%8E%E7%89%88%E6%9C%AC%22%5D%0A%20%20C5%20--%3E%20C6%5B%22%E5%AE%8F%E8%A7%82%2F%E9%A3%8E%E6%A0%BC%E4%B8%8E%E6%9D%A1%E4%BB%B6%E5%8C%96%EF%BC%9APIT%20%E7%8A%B6%E6%80%81%E5%8F%98%E9%87%8F%22%5D%0A%20%20C6%20--%3E%20C7%5B%22%E8%BE%B9%E9%99%85%E8%B4%A1%E7%8C%AE%EF%BC%9A%E7%9B%B8%E5%AF%B9%E8%B4%A6%E6%9C%AC%E7%9A%84%E6%AE%8B%E5%B7%AE%20IR%22%5D%0A%20%20C7%20--%3E%20C8%5B%22%E6%9A%B4%E9%9C%B2%E7%AE%A1%E7%90%86%EF%BC%9A%E6%BC%82%E7%A7%BB%E3%80%81%E9%99%90%E5%80%BC%E3%80%81%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20C8%20--%3E%20C9%5B%22%E6%8A%A5%E5%91%8A%EF%BC%9AN%20%E4%B8%8E%E7%BB%8F%E6%B5%8E%E5%B9%85%E5%BA%A6%22%5D%0A%20%20C9%20--%3E%20C10%5B%22%E5%A4%8D%E7%8E%B0%EF%BC%9A%E6%89%B0%E5%8A%A8%E8%A1%A8%E4%B8%8E%E5%BD%92%E6%A1%A3%22%5D%0A%20%20C10%20--%3E%20C1%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p>十环各有一个最常见的死法。构造：等权加月度调仓，把反转红利记成 alpha。正交化：控制集挑到结论满意为止——那不是检验，是搜索。拥挤：单一代理当开关。生命周期：把体制性回撤当死亡，或把真衰减当噪声扛住。分类学：同家族重复配置，防御风格买了三份。宏观与条件化：状态变量用了修订后的最终值，整个条件设定是未来函数。边际贡献：拿独立 Sharpe 决策，无视与账本的相关。暴露管理：事前与事后从不对账，模型脱钩无人知晓。报告：隐去 N，把挑出的最大 t 当单检验解读。复现：只对主表不做扰动，把约定差异误判为复现失败，或硬凑参数。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把课程收成三句话带走。</p><p><span class="marginnote">「相对什么成立」可以类比物理测量必须写明参考系：说「火车时速 300 公里」而不说相对谁测，这句话就不完整。同理，「残差 IR 1.0」要写成「相对市值加贝塔控制集的 1.0」——参考系换了，同一个数字可能从显著跌到平凡。省略参考系的结论，不是错，是无法被检验。</span>第一句：因子是约定与数据的联合产物，约定要显式，结论要带「相对」。第二句：因子的价值是时变的、状态依赖的、且必须相对账本度量——所以治理（拥挤状态、衰减台账、限值对账）与统计同样重要。第三句：研究的产出是证据链而不是数字，报告与复现是证据链的接口。这三句话与「跑个回测看夏普」的区别：后者在每一环都省略了「相对什么成立」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么把流水线闭环——图中最后一道箭头指回构造？因为复现与运行的反馈会改变构造决策：扰动表告诉你哪个约定承载结论，衰减台账告诉你哪条假设死了——这些信息流回下一轮构造，形成学习回路。</p><p><span class="marginnote">为什么这一步重要：没有失败台账的研究部门，会在「等权、月度调仓、无控制集」这同一组约定上反复发现同一类假阳性——每个新人都把旧陷阱重新踩一遍。有台账的部门把「约定 × 死因」归档，构造新因子时先查清单。存活率的差异，来自死过的地方有没有被记住。</span></p>',7)),(A(),t(i,null,{default:a(()=>[n(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20FAIL%5B%22%E5%9B%A0%E5%AD%90%E6%AD%BB%E4%BA%A1%EF%BC%9A%E6%89%B0%E5%8A%A8%E8%A1%A8%E4%B8%8E%E8%A1%B0%E5%87%8F%E5%8F%B0%E8%B4%A6%22%5D%20--%3E%20WHY%5B%22%E5%AE%9A%E4%BD%8D%EF%BC%9A%E5%93%AA%E4%B8%AA%E7%BA%A6%E5%AE%9A%E6%89%BF%E8%BD%BD%E4%BA%86%E7%BB%93%E8%AE%BA%22%5D%0A%20%20WHY%20--%3E%20LEDG%5B%22%E5%A4%B1%E8%B4%A5%E6%B8%85%E5%8D%95%EF%BC%9A%E7%BA%A6%E5%AE%9A%20%C3%97%20%E6%AD%BB%E5%9B%A0%20%E5%BD%92%E6%A1%A3%22%5D%0A%20%20LEDG%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E6%9E%84%E9%80%A0%EF%BC%9A%E5%85%88%E6%9F%A5%E6%B8%85%E5%8D%95%E5%86%8D%E5%8A%A8%E6%89%8B%22%5D%0A%20%20NEXT%20--%3E%20NEWCAND%5B%22%E6%96%B0%E5%80%99%E9%80%89%E5%9B%A0%E5%AD%90%22%5D%0A%20%20NEWCAND%20--%3E%20FAIL%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p>没有闭环的研究部门反复在同一类约定上发现同一类假阳性；有闭环的部门，每个因子的死亡都在提高下一批因子的存活率。本课程没有引入新的数学：它把主干课的因子知识接上了约定、状态、账本与治理四个维度，让结果从「一组回测数字」变成「可治理、可证伪、可交接的对象」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不进入组合构建的优化器细节——因子确定之后的权重问题（数值稳定性、正则化、再平衡）是下一门课的对象，那里默认你能交付一个约定显式、状态可查、报告完整的因子。机器学习因子是另一条支线，本课程的检验与治理纪律对它原样适用，只是 N 更大、折价更重。方法论不替你判断经济机制：家族标签是先验，风险补偿与行为的划分常不可检验——它收敛于让错误可被发现。</p><p><span class="marginnote">常见误区：把家族地图当成因果分类。同一个「动量」标签下，可能既有行为学解释（反应不足），也有风险补偿解释（承担崩溃风险）——两者给出的预测不同，但样本内往往分不开。地图的用途是「防重复配置、声明坐标版本」，不是宣称「我懂了这个因子为什么赚钱」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>十环流水线：构造、正交化、拥挤、生命周期、分类、宏观/条件化、边际贡献、暴露、报告、复现；每环出口是下环入口。</li><li>每环都有一种典型死法，收束于「相对什么成立」被省略之处。</li><li>三句话带走：约定显式、价值相对且时变、产出是证据链；闭环让每个因子的死亡提高下一批因子的存活率。</li><li>本课程到此收束；因子确定之后的权重与优化，交给组合构建的课程。</li><li>出处：本课程各课出处汇总——Fama &amp; French, <em>JFE</em>, 1993/2015；Carhart, <em>JF</em>, 1997；Grinold &amp; Kahn, <em>Active Portfolio Management</em>；Harvey, Liu &amp; Zhu, <em>RFS</em>, 2016；McLean &amp; Pontiff, <em>JF</em>, 2016。</li></ul>',6))])}const u=l(p,[["render",C]]);export{c as __pageData,u as default};
